/**
 * Messages for the Agents area (components/agents/**), in every language.
 * Keys are prefixed `agents.` so they never collide with another file.
 * English is the source; the other tables are Partial and fall back to
 * English per key. Same rules as messages/en.ts: `{name}` placeholders kept
 * in every language, and no em dash or en dash anywhere
 * (shared/copy-rules.ts), nor a full-width dash in Japanese, Chinese or
 * Korean. No advice vocabulary, no exclamation marks, in any language;
 * components/agents/agents-copy.test.ts holds every table to that.
 *
 * Plurals are separate keys (`.one`, `.other`) picked with Intl.PluralRules
 * (`sayCount` in components/agents/agent-format.ts); every table carries both,
 * even a language whose rules only ever pick "other".
 *
 * `agents.line.*` are the engine's sentences, by the `AgentLine` code the
 * engine sends (shared/agent-types.ts, src/main/agents). Tickers, company
 * names, SEC form names, event codes, the reader's own brief and anything
 * the model writes are never translated: they arrive as values.
 */
